package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
public class RootImageSeriesScopeTest {
 @Test public void exactlyThreeIndependentSlots(){assertTrue(RootImageSeriesScope.ACTIVE);assertEquals(3,RootImageSeriesScope.MAX_FRAMES);for(int i=1;i<=3;i++){assertTrue(RootImageSeriesScope.validIndex(i));assertEquals("FRAME_"+i,RootImageSeriesScope.slot(i));}for(int i:new int[]{Integer.MIN_VALUE,-1,0,4,Integer.MAX_VALUE}){assertFalse(RootImageSeriesScope.validIndex(i));assertThrows(SecurityException.class,()->RootImageSeriesScope.slot(i));}}
 @Test public void halfOpenWindowAndParentAdmissionMargin(){long s=RootImageSeriesScope.STARTS_UTC,e=RootImageSeriesScope.EXPIRES_UTC;assertFalse(RootImageSeriesScope.current(s-1));assertTrue(RootImageSeriesScope.current(s));assertTrue(RootImageSeriesScope.current(e-1));assertFalse(RootImageSeriesScope.current(e));assertTrue(RootImageSeriesScope.admissionCurrent(e-180001));assertFalse(RootImageSeriesScope.admissionCurrent(e-180000));}
 @Test public void independentBoundedParentAndEachFrame(){long u=RootImageSeriesScope.STARTS_UTC;assertEquals(181000,RootImageSeriesScope.sessionDeadline(1000,u));assertEquals(91000,RootImageSeriesScope.deadline(1000,u,181000));assertEquals(181000,RootImageSeriesScope.deadline(101000,u+100000,181000));assertEquals(1500,RootImageSeriesScope.deadline(1000,u,1500));assertEquals(1001,RootImageSeriesScope.deadline(1000,RootImageSeriesScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidClocksNeverIssue(){long u=RootImageSeriesScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootImageSeriesScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootImageSeriesScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootImageSeriesScope.sessionDeadline(1,RootImageSeriesScope.EXPIRES_UTC));assertThrows(SecurityException.class,()->RootImageSeriesScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootImageSeriesScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootImageSeriesScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void namespaceAndOldWindowsAreIndependent(){assertNotEquals(RootImageSeriesScope.DIRECTORY,RootFamilyDiagnosticProfile.DIRECTORY);assertNotEquals(RootImageSeriesScope.DIRECTORY,RootCaptureScope.PREFLIGHT_DIRECTORY);assertNotEquals(RootImageSeriesScope.DIRECTORY,AutonomousRewardCardScope.DIRECTORY);assertTrue(RootImageSeriesScope.current(RootFamilyDiagnosticProfile.EXPIRES_UTC));assertFalse(RootFamilyDiagnosticProfile.current(RootFamilyDiagnosticProfile.EXPIRES_UTC));assertThrows(SecurityException.class,()->RootImageSeriesScope.store(null,1));assertThrows(SecurityException.class,()->RootImageSeriesScope.store(Path.of("unused"),4));}
 @Test public void durableStoreKeepsCreateNewAndForceWithoutRecovery()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootImageSeriesScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootImageSeriesScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("thisClaimFrames=1 inputs=0"));}
}
